L["1 item on the bar"] = "1 objeto en la barra"
L["1 minute"] = "1 minuto"
L["1 paladin in your group"] = "1 paladín en tu grupo"
L["1 player has their own blessing"] = "1 jugador tiene su propia bendición"
L["1 profile on this account"] = "1 perfil en esta cuenta"
L["1 raid"] = "1 banda"
L["1 runs Naowh Forever"] = "1 usa Naowh Forever"
L["1 setting changed from its default"] = "1 ajuste cambiado de su valor predeterminado"
L["1 spell"] = "1 hechizo"
L["1 Unspent Talent Point"] = "1 punto de talento sin gastar"
L["1. PICK YOUR BARS"] = "1. ELIGE TUS BARRAS"
L["100%  (default)"] = "100%  (predeterminado)"
L["100%, native resolution"] = "100%, resolución nativa"
L["12-hour clock"] = "Reloj de 12 horas"
L["16x Anisotropic"] = "Anisotrópico 16x"
L["2. ALSO KEEP"] = "2. CONSERVAR TAMBIÉN"
L["24-Hour Clock"] = "Reloj de 24 horas"
L["24-hour clock"] = "Reloj de 24 horas"
L["3. NAME AND SAVE"] = "3. NOMBRA Y GUARDA"
L["30, while the game is not in focus"] = "30, mientras el juego no está en primer plano"
L[": copy ID or Wowhead link"] = ": copiar ID o enlace de Wowhead"
L[": mail expiring soon on "] = ": correo que expira pronto en "
L["; buys at vendors"] = "; se compra a vendedores"
L["<AFK>"] = "<Ausente>"
L["<DND>"] = "<No molestar>"
L["[Where?]"] = "[¿Dónde?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "Un /thank a todos a tu alrededor cuando el juego no puede nombrar a quien lanzó el hechizo."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "Un enlace [¿Dónde?] tras un susurro de alguien cuya zona no se conoce. Al hacer clic se ejecuta un /who y se muestra su zona; sus siguientes mensajes quedan etiquetados."
L["A banner and a sound when one of them joins your group."] = "Un aviso y un sonido cuando uno de ellos se une a tu grupo."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "Una barra en la amenaza a la que quitarías la amenaza, para leer fácilmente cuánto falta."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "Una barra para los golpes de tu objetivo, que se reinicia con cada golpe físico que recibes mientras te tiene como objetivo y se acorta cuando bloquea con arma. Es una estimación: el juego no dice quién te golpeó ni con qué, así que otros atacantes, ataques especiales físicos y sangrados también la reinician."
L["A bar left out is not touched by an import."] = "Una barra omitida no se toca al importar."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "Una barra por miembro del grupo con su nivel y cuánto avanzó en él. Cada miembro que usa Naowh Forever comparte su experiencia, incluso con esto desactivado; los demás muestran su nivel. Se actualiza al terminar el combate. Muévela en el Editor de HUD."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "Una barra con el nombre, una flecha de giro y la distancia, mientras haya un punto de ruta."
L["A batch of ten, four done, as it shows while you craft."] = "Una tanda de diez, cuatro hechas, como se ve mientras fabricas."
L["A black outline round the clock."] = "Un contorno negro alrededor del reloj."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "Un contorno negro alrededor de los FPS / MS y los contadores, en lugar de la sombra suave."
L["A black outline round the text, in place of the soft shadow."] = "Un contorno negro alrededor del texto, en lugar de la sombra suave."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "Un botón por conjunto: clic para equiparlo, Mayús+clic para guardar lo que llevas en él, Ctrl+clic para renombrarlo, clic derecho para cambiar su ícono y + para guardar uno nuevo. El conjunto que llevas está resaltado. Muévelo en el Editor de HUD."
L["A button that flags or unflags you for PvP, showing which you are."] = "Un botón que activa o desactiva tu JcJ y muestra cuál tienes."
L["A campfire in range and Camp Benefits about to run out."] = "Una fogata cerca y los Beneficios de campamento a punto de terminar."
L["A campfire in range and no Camp Benefits."] = "Una fogata cerca y sin Beneficios de campamento."
L["A campfire is in range"] = "Hay una fogata cerca"
L["A card behind the text, a soft dark fade, or nothing at all."] = "Una tarjeta detrás del texto, un fundido oscuro suave o nada."
L["A card over the pin with what it is and how far."] = "Una tarjeta sobre el marcador con lo que es y a qué distancia está."
L["A cast part way through, swept around the ring."] = "Un lanzamiento a medias, barrido alrededor del anillo."
L["A cast someone interrupted, held for the fade time."] = "Un lanzamiento que alguien interrumpió, mostrado durante el tiempo de desvanecimiento."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "Un lanzamiento mientras tu interrupción está en tiempo de reutilización, con la marca donde vuelve."
L["A cast while your interrupt is ready."] = "Un lanzamiento mientras tu interrupción está lista."
L["A cast you cannot interrupt, with its shield."] = "Un lanzamiento que no puedes interrumpir, con su escudo."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "Un personaje aparece aquí después de iniciar sesión con él con el Rastreador de instancias activado. Rastrear alters muestra los demás: experiencia de descanso y durabilidad, de la última vez que ese personaje inició sesión."
L["A choice among its rewards: pick this one."] = "Una opción entre sus recompensas: elige esta."
L["A command name can only use letters, numbers and underscores."] = "Un nombre de comando solo puede usar letras, números y guiones bajos."
L["A consumable or personal buff with less time than this left counts as missing."] = "Un consumible o beneficio personal con menos tiempo que este cuenta como faltante."
L["A crosshair at the middle of your screen."] = "Una mira en el centro de tu pantalla."
L["A cup beside a healer who is drinking."] = "Una taza junto a un sanador que está bebiendo."
L["A custom command can't reload. Type /reload."] = "Un comando personalizado no puede recargar. Escribe /reload."
L["A dark or light fill and edge behind each line, or none."] = "Un relleno y borde oscuro o claro detrás de cada línea, o ninguno."
L["A dark panel behind the icons."] = "Un panel oscuro detrás de los íconos."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "Una puerta en cada entrada de calabozo y banda del mapa del mundo, para los lados que indica el Diario. Pasa el cursor para ver los niveles y haz clic para un punto de ruta."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "Un punto en una casilla donde te espera un encantamiento mejor para tu nivel: pasa el cursor para ver el consejo y haz clic para pedirlo en Comercio."
L["A fading trail behind the cursor."] = "Una estela que se desvanece detrás del cursor."
L["A few quick steps for %s only, its own modules included."] = "Unos pasos rápidos solo para %s, sus propios módulos incluidos."
L["A game that opens when a flight starts and closes when you land."] = "Un juego que se abre al iniciar un vuelo y se cierra al aterrizar."
L["A gear set called %s already exists."] = "Ya existe un conjunto de equipo llamado %s."
L["A glow on the moving edge of the fill."] = "Un brillo en el borde móvil del relleno."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "Una cadena de misiones oculta por todo Azeroth: haz clic en cada cosa del mundo por turnos. Da mucha experiencia y termina en el Saco de dormir acogedor; descansa en él para obtener una bonificación de experiencia."
L["A key that opens Group Inspect."] = "Una tecla que abre la Inspección de grupo."
L["A key that shows a boss's loot at your cursor."] = "Una tecla que muestra el botín de un jefe en tu cursor."
L["A key that uses this item."] = "Una tecla que usa este objeto."
L["A later point needs it. "] = "Un punto posterior lo necesita. "
L["A later step."] = "Un paso posterior."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "Una línea por cada misión que entregas, con la experiencia y el dinero que dio. Los objetos de recompensa se muestran en sus propias líneas."
L["A line for every reputation gain, from quests and kills alike."] = "Una línea por cada ganancia de reputación, tanto de misiones como de muertes."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "Una línea por la experiencia de cada muerte. La experiencia de misión está en la línea de la misión."
L["A line from the pin down to a map pin's or corpse's spot."] = "Una línea desde el marcador hasta el lugar de un marcador del mapa o de un cadáver."
L["A line in chat with the item's link."] = "Una línea en el chat con el enlace del objeto."
L["A line in their color on their player tooltip."] = "Una línea con su color en la descripción emergente del jugador."
L["A line to share them with."] = "Una línea para compartirlos."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "Una línea bajo el ID que dice qué teclas lo copian (Ctrl+Mayús+C: copiar ID o enlace de Wowhead). Desactivado, el atajo sigue funcionando; solo no se muestra la línea."
L["A look you do not have yet|r"] = "Una apariencia que aún no tienes|r"
L["a macro made on this character"] = "una macro creada en este personaje"
L["A macro this character does not have yet: the import makes it."] = "Una macro que este personaje aún no tiene: la importación la crea."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "Un botón del minimapa que abre %s. /nf%s hace lo mismo, y la Barra superior también puede llevarlo. Guardado para esta computadora."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Una línea de pesos de Naowh o una exportación EP de WoWSims (en WoWSims: Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Una línea de pesos de Naowh o una exportación EP de WoWSims."
L["A new session, before any experience."] = "Una nueva sesión, antes de cualquier experiencia."
L["A parry by your target took 40% off its swing."] = "Un bloqueo con arma de tu objetivo le quitó un 40% a su golpe."
L["A party of five, a card each."] = "Un grupo de cinco, una tarjeta cada uno."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "La puntuación de un jugador en su descripción emergente. Quien usa Naowh Forever comparte la suya; la de los demás se lee de su equipo al pasar el cursor, dentro del alcance de inspección y fuera de combate."
L["A profile"] = "Un perfil"
L["a quest"] = "una misión"
L["A quest reward for the other faction; try the Auction House."] = "Una recompensa de misión de la otra facción; prueba en la casa de subastas."
L["A raid for %d players"] = "Una banda de %d jugadores"
L["A raid, a row each."] = "Una banda, una fila cada uno."
L["A rare someone else is fighting."] = "Un raro con el que otro está peleando."
L["A rare you have killed before."] = "Un raro que ya eliminaste."
L["A rare you have not killed yet."] = "Un raro que aún no eliminaste."
L["A reward from the quest "] = "Una recompensa de la misión "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "Un anillo alrededor del cursor para que nunca lo pierdas en un combate intenso, con tu tiempo de reutilización global y tus lanzamientos barridos a su alrededor."
L["A round in progress."] = "Una ronda en curso."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "Una fila de íconos para beneficios faltantes de comida, frasco, elixir y pergamino, tu propio beneficio de clase y los beneficios de clase que faltan en tu grupo. Solo fuera de combate: el juego bloquea tus beneficios a los addons en combate, así que los íconos conservan lo que mostraban. Pasa el cursor sobre uno para elegir un objeto que llevas para usarlo. Muévelos en el Editor de HUD."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "Un oro por hora continuo junto a la línea más reciente, que cuenta el dinero y el valor de los objetos desde tu primer botín de esta sesión."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "Un botón Escanear precios en la casa de subastas. Lee cada publicación y guarda el precio de compra inmediata más bajo de cada objeto, para este reino y facción. Blizzard permite un escaneo completo cada 15 minutos."
L["A junk icon on the bag slot of each item marked as junk."] = "Un ícono de basura en la casilla de la bolsa de cada objeto marcado como basura."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "Un segundo panel para tu foco, para controlar el tiempo de Porrazo o Polimorfia en un enemigo mientras peleas con otro."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "Un conjunto que se pone solo mientras montas o descansas, y el conjunto que tenías vuelve después."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "Un juego de disparos para los vuelos: haz clic en las razas de la otra facción lo más rápido posible."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "Un breve destello de texto al entrar y salir de combate. Muévelo en el Editor de HUD."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "Una barra pequeña con tu próxima visita al instructor y tu oro, para dejarla visible mientras subes de nivel. Muévela arrastrándola."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "Una barra de salud pequeña para el otro tanque de tu grupo, visible mientras tanqueas: rol de tanque, Forma de oso, Actitud defensiva o Furia recta. El otro tanque es quien tenga el rol de tanque o la asignación de Tanque principal de la banda. Haz clic para seleccionarlo. Los cambios hechos en combate se aplican al terminar el combate. Muévela en el Editor de HUD."
L["A soft glow around Naowh's arrow."] = "Un brillo suave alrededor de la flecha de Naowh."
L["A soft glow beside each icon."] = "Un brillo suave junto a cada ícono."
L["A soft glow round it in your accent color."] = "Un brillo suave alrededor en tu color de acento."
L["A soft glow round it in your rank's color."] = "Un brillo suave alrededor en el color de tu rango."
L["A soft ring pulses around each target."] = "Un anillo suave pulsa alrededor de cada objetivo."
L["a sound to refresh"] = "un sonido para renovar"
L["A sound, or the Speech text read aloud, as each cast starts."] = "Un sonido, o el texto de voz leído en voz alta, al iniciar cada lanzamiento."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "Un sonido, o el texto de voz leído en voz alta. La conversión de texto a voz puede trabarse en algunas PC, ya que el juego espera mientras Windows lo dice; un sonido no cuesta nada."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "Un hechizo que una importación no pudo colocar porque aún no lo conoces va a su casilla guardada cuando lo aprendas, a menos que hayas puesto otra cosa ahí."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "Un botón Apilar en la tarjeta cuando se pueden combinar montones incompletos de un objeto."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "Una estrella en el mapa del mundo por cada raro que no eliminaste, donde es más probable que esté. Pasa el cursor sobre una para ver el raro y su botín, sus otros puntos de aparición y, si patrulla, su ruta; haz clic para un punto de ruta y clic derecho para mantener visibles sus puntos y su ruta."
L["A string to share it with."] = "Una cadena para compartirlo."
L["A supporter"] = "Un colaborador"
L["A team member"] = "Un miembro del equipo"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "Un texto en la barra: haz clic en él en la vista previa para cambiarlo. Cada texto se muestra en un solo lugar de la barra: elegir uno que se muestra en otro lado lo mueve allí."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "Una marca en la barra donde tu interrupción sale de tiempo de reutilización. Oculta mientras está lista."
L["A title bar naming the mob the threat is on."] = "Una barra de título con el nombre del enemigo que tiene la amenaza."
L["A trained spell drops into its saved slot."] = "Un hechizo entrenado cae en su casilla guardada."
L["a vendor sells the formula"] = "un vendedor vende la fórmula"
L["A warning when a rare is near"] = "Un aviso cuando hay un raro cerca"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "Un aviso cuando hay un raro cerca: cuando aparece su placa de nombre, pasas el cursor sobre él o lo seleccionas. Una tarjeta con su retrato: haz clic derecho para cerrarla, y su marcador pone un punto de ruta hacia el raro. Muévela en el Editor de HUD."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "Un aviso mientras un cazador o brujo no tiene una mascota fuera. Se ignora a un brujo que sacrificó a su demonio. Muévelo en el Editor de HUD."
L["A word of your own on the icon."] = "Una palabra tuya en el ícono."
L["A world drop from %d kinds of mob"] = "Botín del mundo de %d tipos de enemigos"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "Un cuestionario de WoW para fogatas y vuelos, o en cualquier momento con /naowh quiz."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "Un ! amarillo en el mapa del mundo en cada personaje que da una misión que puedes recoger y que aún da experiencia. Pasa el cursor para ver las misiones; haz clic para un punto de ruta."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "Ya no se muestra una zona más antigua que esto, porque es probable que el jugador ya se haya ido."
L["Abandon %s?"] = "¿Abandonar %s?"
L["Abilities"] = "Habilidades"
L["about "] = "unos "
L["about %d:%02d"] = "unos %d:%02d"
L["About %s at your last scan%s%s"] = "Unos %s en tu último escaneo%s%s"
L["About %s spent"] = "Unos %s gastados"
L["About a minute."] = "Alrededor de un minuto."
L["Above"] = "Encima"
L["Acc."] = "Prec."
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "Acento: falta la bendición de clase. Más claro: por terminarse. Más intenso: solo jugadores con su propia bendición."
L["Accept Quests"] = "Aceptar misiones"
L["Accept Shared Dungeon Quests"] = "Aceptar misiones de calabozo compartidas"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "Acepta una misión en cuanto se abre su texto. Usa el modificador para leerla primero."
L["Accepts dungeon quests your group shares with you straight away."] = "Acepta al instante las misiones de calabozo que tu grupo comparte contigo."
L["Accepts shared quests"] = "Acepta misiones compartidas"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "Acepta la ventana emergente en pantalla: una invocación, una resurrección, una invitación de grupo."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "Acepta, entrega y comparte misiones por ti, y recuerda la recompensa que guardaste para una misión. El modificador las omite o las activa, según diga Qué hace el modificador."
L["Account"] = "Cuenta"
L["Account "] = "Cuenta "
L["Account macros"] = "Macros de la cuenta"
L["Account this hour: %d of %d"] = "Cuenta en esta hora: %d de %d"
L["Accuracy"] = "Precisión"
L["Action Bars is switched off."] = "Barras de acción está desactivado."
L["Action Bars' own window, with your class's saved sets."] = "La ventana propia de Barras de acción, con los conjuntos guardados de tu clase."
L["Active"] = "Activo"
L["Activity Bar"] = "Barra de actividad"
L["Activity Bar Color"] = "Color de la barra de actividad"
L["Activity Bar Height"] = "Altura de la barra de actividad"
L["Add %d item to your junk list: %s%s?"] = "¿Agregar %d objeto a tu lista de basura: %s%s?"
L["Add %d items to your junk list: %s%s?"] = "¿Agregar %d objetos a tu lista de basura: %s%s?"
L["Add %d macro as character macros?%s"] = "¿Agregar %d macro como macro de personaje?%s"
L["Add %d macros as character macros?%s"] = "¿Agregar %d macros como macros de personaje?%s"
L["Add %s"] = "Agregar %s"
L["Add %s (%d items) as a new BiS list?"] = "¿Agregar %s (%d objetos) como nueva lista BiS?"
L["Add %s to the Consumable Bar?"] = "¿Agregar %s a la Barra de consumibles?"
L["Add a backup pick"] = "Agregar una opción de respaldo"
L["Add a Button"] = "Agregar un botón"
L["Add a stat"] = "Agregar una estadística"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Agrega un ID de objeto o importa una lista. La comida cuenta cualquier beneficio Bien alimentado y otros objetos su propio beneficio; agrega ID de hechizos de beneficio solo para un objeto que da otro. No se agrega nada automáticamente. Pasa el cursor sobre un recordatorio para elegir un objeto configurado de tus bolsas. Los recordatorios se pausan en combate; los menús de objetos funcionan fuera de combate. Cuándo y dónde se muestran está en AuraBuffs > Configuración."
L["Add consumables, put them in order, and set each one up."] = "Agrega consumibles, ordénalos y configura cada uno."
L["Add Items"] = "Agregar objetos"
L["Add Latency"] = "Agregar latencia"
L["Add macros someone shared with you."] = "Agrega macros que alguien compartió contigo."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "Agrega o quita tus comandos, activa o desactiva cada uno, o restaura los predeterminados."
L["Add Slash Command"] = "Agregar comando"
L["Add the %s build %s (%d points)?"] = "¿Agregar la build de %s %s (%d puntos)?"
L["Add Themes to RestedXP"] = "Agregar temas a RestedXP"
L["Add to BiS List"] = "Agregar a la lista BiS"
