L["Add to the Right Side"] = "Agregar al lado derecho"
L["Add your consumables, put them in order, set each one up."] = "Agrega tus consumibles, ordénalos y configura cada uno."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Agrega tus propias líneas a las macros de bolsa. Se conservan después del objeto, sin importar lo que haya en tus bolsas."
L["Added %d consumable to the Consumable Bar."] = "Se agregó %d consumible a la Barra de consumibles."
L["Added %d consumables to the Consumable Bar."] = "Se agregaron %d consumibles a la Barra de consumibles."
L["Added %d consumables; %d were already listed or past the %d limit."] = "Se agregaron %d consumibles; %d ya estaban en la lista o superaban el límite de %d."
L["Added %d of %d: %s."] = "Se agregaron %d de %d: %s."
L["Added %d."] = "Se agregaron %d."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "Se agregó %s a este personaje. Arrástrala a una barra desde la ventana de macros del juego (/macro)."
L["Added %s to your BiS %s as #%d."] = "Se agregó %s a tu BiS de %s como #%d."
