L["Addon List"] = "Lista de addons"
L["Addon Memory"] = "Memoria de addons"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "Agrega \"- [1] + Agregar a la lista\" bajo los componentes de una receta: los materiales que Comprar en la casa de subastas compraría para esa cantidad de fabricaciones van a una lista de compras, desde cualquier lugar. En la casa de subastas la lista se muestra al lado: Revisar precios busca cada uno y avisa en rojo cuando uno está muy por encima de tu último escaneo, y luego Comprar todo recorre la lista un material a la vez, comprando cada uno solo cuando confirmas su precio final. Si un material sale más barato fabricado con sus partes, como una barra a partir de mineral, se compran sus partes."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "Agrega una columna Bolsas a los componentes de la receta elegida, que muestra cuántos de cada uno llevas."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "Agrega una columna Banco a los componentes de la receta elegida, que muestra cuántos de cada uno hay en tu banco."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "Agrega un botón a la ventana emergente que cambia cada rango inferior de tus barras por el rango más alto que conoces. Las barras de teclado y de mando quedan en la misma casilla. Haz clic derecho en un hechizo de la ventana para conservar sus rangos inferiores y bajar de rango. Los cambios de rango solo ocurren fuera de combate."
L["Adds a Land button to come down at the next stop on the way."] = "Agrega un botón Aterrizar para bajar en la siguiente parada del camino."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "Agrega una línea que marca cualquier casilla cuyo encantamiento falte o difiera de los que capturaste con Capturar encantamientos actuales. Pasa el cursor para ver los detalles."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "Agrega a la descripción emergente de un hechizo de maná su sanación o daño por maná y por segundo."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "Agrega un segundo número naranja junto a cada receta: cuántas podrías fabricar después de comprar los componentes que venden los vendedores, como Fundente débil o Hilo grueso. Los componentes de la receta indican entonces cuántos comprar de cada uno."
L["Adds how long the visit lasted."] = "Agrega cuánto duró la visita."
L["Adds target and focus switching to the meter's title bar."] = "Agrega el cambio de objetivo y foco a la barra de título del medidor."
L["Adds the average experience here."] = "Agrega la experiencia promedio aquí."
L["Adds the coins looted."] = "Agrega las monedas saqueadas."
L["Adds the consumables in your bags that are not on the bar yet."] = "Agrega los consumibles de tus bolsas que aún no están en la barra."
L["Adds the deaths."] = "Agrega las muertes."
L["Adds the experience gained."] = "Agrega la experiencia obtenida."
L["Adds the materials for one more craft."] = "Agrega los materiales para una fabricación más."
L["Adds the Naowh themes to RestedXP's theme list."] = "Agrega los temas de Naowh a la lista de temas de RestedXP."
L["Adds the reputation gained."] = "Agrega la reputación obtenida."
L["Adds the visits at this level."] = "Agrega las visitas en este nivel."
L["Adds the visits until you level."] = "Agrega las visitas hasta subir de nivel."
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "Agrega tu bonificación de sanación o daño con hechizos; desactivado muestra los números base del hechizo."
