L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "También muestra la ganancia de cada receta a la derecha de su fila en la lista, en verde o rojo. Las recetas sin ganancia conocida no muestran nada."
L["Also thanks players in your party or raid."] = "También agradece a los jugadores de tu grupo o banda."
