L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "Un error de \"El inventario está lleno\" muestra la fila durante 20 segundos, aunque haya más casillas libres que el umbral de arriba."
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "Un alter que ya tiene esta macro, por nombre y texto o solo por texto, usa la suya."
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "Un botón Alters junto a la pestaña Enviar del buzón enumera tus personajes de este reino y facción con su nivel y oro. Elige uno para llenar el campo Para."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "Un botón Adjuntar junto a la pestaña Enviar del buzón: adjunta todos los objetos comerciables, un tipo de objeto comerciable o tu equipo no ligado con un clic."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "Un ID que el juego mantiene oculto: Ocultar línea lo deja fuera de la descripción emergente, Mostrar ocultos muestra la línea con Oculto en lugar del número."
L["An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster."] = "Un objeto que vale más en la casa de subastas que en un vendedor se valora a su precio de subasta, de tu último Escanear precios o de TradeSkillMaster."
