L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "Cada visita a un calabozo o banda mientras el Rastreador de instancias está activado: cuánto tiempo estuviste dentro, las monedas que saqueaste y la experiencia que obtuviste. La reputación obtenida se enumera bajo la visita. Volver al mismo grupo dentro de la hora, antes de reiniciarlo, continúa esa visita, y el tiempo afuera no cuenta. Los demás personajes se quedan guardados y se muestran aquí cuando Rastrear alters está activado. Las reparaciones y ventas a vendedores no cuentan. Las visitas más antiguas salen del final de la lista."
L["Each line fades out after %ss."] = "Cada línea se desvanece después de %s s."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "Cada una es una macro de cuenta. Ponla en una barra una vez y se mantiene actualizada sola: saquea una poción mejor, conjura comida nueva o recoge vendas y la macro se reescribe para usar lo mejor que llevas.\n\nEl juego no permite que las macros cambien en pleno combate, así que un cambio en combate espera a que termine."
L["Each point of the trail in a color of its own."] = "Cada punto de la estela en su propio color."
L["Each slot's item level, in its icon's corner."] = "El nivel de objeto de cada casilla, en la esquina de su ícono."
