L["How close a book has to be before it pings."] = "Qué tan cerca debe estar un libro para que avise."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "Cuánto antes puedes pulsar tu siguiente hechizo antes de que termine el actual, en milisegundos. De 100 a 400 sirve para la mayoría: más bajo responde mejor, más alto tolera más la latencia. Cuerpo a cuerpo alrededor de tu ping + 100, a distancia alrededor de tu ping + 150."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "En qué punto empieza a desvanecerse un ícono, de 0% (de inmediato) a 95% (al final)."
