L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "Una vez que escaneaste la casa de subastas (Escanear precios), la receta elegida muestra lo que cuesta comprar sus componentes y por cuánto se vende el objeto, y la ganancia tras la comisión del 5% de la casa de subastas. Cada componente se valora a su precio más bajo: el de un vendedor si ya viste que lo vende, si no, la compra inmediata más baja de tu último escaneo. Desmarca un componente que ya tengas para dejarlo fuera del costo, en todas las recetas que lo usan. Pasa el cursor sobre las líneas para ver el desglose."
L["One addon"] = "Un addon"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "Una barra por arma, sincronizada con el propio evento de golpe del juego, así que la aceleración por bloqueo con arma, los reinicios de golpe y la celeridad siempre son correctos. Muévelas en el Editor de HUD."
L["One Fewer"] = "Uno menos"
L["One item per click: the game needs a click for every disenchant."] = "Un objeto por clic: el juego necesita un clic para cada desencantamiento."
L["One More"] = "Uno más"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "Un número para el equipo de un personaje, en la escala de nivel de objeto: 26.4 significa equipo que vale un conjunto de épicos de nivel 26. El tuyo siempre está en el muñeco de la lista BiS."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "Un susurro por línea, elegido al azar; {buff} y {name} se completan."
