L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Abre la ventana de AuraBuffs, donde agregas cada objeto por su ID de objeto y su ID de hechizo de beneficio."
L["Opens the Consumable Bar's settings."] = "Abre la configuración de la Barra de consumibles."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Abre la tarjeta de copia con un hechizo de ejemplo. Selecciona el ID o el enlace y luego Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Abre la configuración del Rastreador de misiones del Diario de calabozos."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Abre el Editor de HUD: haz clic en otro elemento de Naowh Forever para que la barra se mueva con él."
L["Opens the Library Books tracker's settings."] = "Abre la configuración del rastreador de Libros de la biblioteca."
L["Opens the planner on its Builds tab."] = "Abre el planificador en su pestaña Builds."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Abre el rastreador de misiones en el mundo, en el calabozo para el que son tus misiones."
