L["Put this bar back in"] = "Volver a incluir esta barra"
L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "Pone una marca de banda en tu foco. Pulsar la macro otra vez sobre el mismo foco borra la marca."
L["Puts back every setting this page has changed, to the value you had before."] = "Restaura todos los ajustes que cambió esta página al valor que tenías antes."
L["Puts back everything changed since the HUD Editor opened."] = "Restaura todo lo cambiado desde que se abrió el Editor de HUD."
L["Puts back the last change. Ctrl + Z."] = "Deshace el último cambio. Ctrl + Z."
L["Puts both back where the game shows them."] = "Devuelve ambos a donde los muestra el juego."
L["Puts every weight of this spec back to the defaults. Asks first."] = "Restablece todos los pesos de esta especialización a los predeterminados. Pregunta primero."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "Pone primero la comida, bebida y pociones 10 o más niveles por debajo de ti, marcadas con un reloj."
L["Puts the bar back on the screen."] = "Devuelve la barra a la pantalla."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "Devuelve los botones de la barra a como venían: el Diario de calabozos y Descubrimiento a la izquierda, la lista BiS y el Planificador de entrenamiento a la derecha."
L["Puts the card back above the middle of the screen, where it starts."] = "Devuelve la tarjeta arriba del centro de la pantalla, donde empieza."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "Pone el objeto más barato en el extremo de la fila en lugar de junto a su ancla."
L["Puts the cheapest item on your cursor, to drop or sell."] = "Pone el objeto más barato en tu cursor, para soltarlo o venderlo."
L["Puts the count just past the icon's edge."] = "Pone el conteo justo fuera del borde del ícono."
L["Puts the key just past the icon's edge."] = "Pone la tecla justo fuera del borde del ícono."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "Pone en tu lista de compras los materiales para esa cantidad de fabricaciones: cada componente marcado que no venden los vendedores, sin importar lo que haya en tus bolsas. Desmarca un componente para omitirlo. En la casa de subastas la lista se muestra al lado, para revisar los precios y comprarlo todo."
L["Puts the popup back where it first showed."] = "Devuelve la ventana emergente a donde apareció primero."
L["Puts the quiz back where it first opened."] = "Devuelve el cuestionario a donde se abrió primero."
L["Puts the text just past the icon's edge."] = "Pone el texto justo fuera del borde del ícono."
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "Pone esta receta en el pedido de la derecha, con la cantidad de fabricaciones y los materiales que aportas. Los cambios hechos aquí después de agregarla también cambian el pedido. Hasta %d recetas por pedido."
L["Puts this set on. In combat, it goes on when the fight ends."] = "Te pone este conjunto. En combate, se pone al terminar el combate."
L["Puts your settings to one of Naowh's setups, or walks you through them again."] = "Ajusta tu configuración a una de las de Naowh, o te guía por ellas otra vez."
