L["The bar and the FPS / MS readout fade to Faded Opacity until you hover them. Their buttons still click while faded."] = "La barra y los FPS / MS se desvanecen a la Opacidad desvanecida hasta que pasas el cursor sobre ellos. Sus botones siguen respondiendo aunque estén desvanecidos."
