L["The best scores of the players you have met, in this mode."] = "Las mejores puntuaciones de los jugadores que conociste, en este modo."
L["The BiS List's own window, and its Stat Weights window."] = "La ventana propia de la lista BiS, y su ventana de Pesos de estadísticas."
L["The BiS rankings behind the BiS List."] = "Las clasificaciones BiS detrás de la lista BiS."
L["The book count is what players report; not confirmed yet."] = "El conteo de libros es lo que reportan los jugadores; aún no está confirmado."
L["The boss or place it comes from."] = "El jefe o el lugar de donde viene."
L["The buffs show while you hover the icon."] = "Los beneficios se muestran al pasar el cursor sobre el ícono."
L["The build's next talent cannot be taken now: your talents are not the build's."] = "El siguiente talento de la build no se puede tomar ahora: tus talentos no son los de la build."
