L["The card at the end of a round."] = "La tarjeta al final de una ronda."
L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "Los objetos más baratos de tus bolsas como una fila de íconos, el más barato primero. Ctrl+clic en un ícono para eliminarlo, o clic para venderlo mientras hay un vendedor abierto. Clic central para ignorar un objeto. Muévela en el Editor de HUD."
L["The class's name, or its class icon, which fits however small the buttons are."] = "El nombre de la clase, o su ícono de clase, que cabe sin importar lo pequeños que sean los botones."
L["The color of the line on the tooltip."] = "El color de la línea en la descripción emergente."
L["The Consumable Bar will ask about those items again."] = "La Barra de consumibles volverá a preguntar por esos objetos."
L["The consumables your reminders watch"] = "Los consumibles que vigilan tus recordatorios"
L["The consumables your reminders watch."] = "Los consumibles que vigilan tus recordatorios."
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "La cadena de misiones oculta del Saco de dormir acogedor, paso a paso."
L["The crowd control on your target; pick which in the Crowd Control card below."] = "El control de masas sobre tu objetivo; elige cuál en la tarjeta Control de masas de abajo."
L["The Ctrl-click line, and Click to sell while a vendor is open."] = "La línea de Ctrl+clic, y Clic para vender mientras hay un vendedor abierto."
L["The cursor left still."] = "El cursor quieto."
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "Los perjuicios sobre tu objetivo que elijas en la tarjeta Perjuicios de abajo, como Golpe mortal."
L["The default is %s."] = "El predeterminado es %s."
L["The default is %s. Click to put it back."] = "El predeterminado es %s. Haz clic para restablecerlo."
L["The Disenchant window cannot open in combat."] = "La ventana de desencantar no se puede abrir en combate."
L["The Dungeon Quest Tracker's window."] = "La ventana del Rastreador de misiones de calabozo."
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "Los calabozos en cuyo territorio se muestra la lista. Los que están en territorio en disputa y las bandas siempre se enumeran. También el interruptor junto a la búsqueda del Diario."
L["The Edit Items window."] = "La ventana Editar objetos."
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "El espacio extra entre tu aura y Furia recta y los botones de clase."
L["The fastest way to any waypoint."] = "El camino más rápido a cualquier punto de ruta."
L["The first %d of %d; type more to narrow it down."] = "Los primeros %d de %d; escribe más para acotar."
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "La primera vez que alguien habla, pregunta su zona a su Naowh Forever con un susurro oculto del addon. Los jugadores sin él nunca ven la pregunta."
L["The flight time to each destination when you hover it on the flight master's map."] = "El tiempo de vuelo a cada destino al pasar el cursor sobre él en el mapa del maestro de vuelo."
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "La fuente de los números de daño y sanación, sobre enemigos y sobre tu personaje. Desactivado deja la fuente del juego como está."
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "La fuente del resto del juego: menús, chat, descripciones emergentes y nombres. Desactivado deja las fuentes del juego como están."
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "La fuente de las ventanas y el HUD de este addon. Los ajustes de fuente de una función la usan a menos que elijan la suya. Guardado para esta computadora.|n|nSe aplica después de un /reload."
L["The FPS / MS readout and the online counts on the buttons."] = "Los FPS / MS y los contadores de conectados en los botones."
L["The FPS / MS readout stays up."] = "Los FPS / MS siguen visibles."
L["The game does not name this fight yet: its kills count once the raid opens."] = "El juego aún no nombra este combate: sus muertes cuentan cuando abra la banda."
L["The game has no PvP rank for you yet. It shows once the season has started."] = "El juego aún no tiene un rango JcJ para ti. Se muestra cuando empiece la temporada."
L["The game has no route for %s, and its quest giver's spot is not known."] = "El juego no tiene ruta para %s, y no se conoce el lugar de quien da la misión."
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "El juego no está pasando mensajes de addons ahora (en un encuentro): vuelve a preguntar después."
L["The game lists no rank rewards for this season yet."] = "El juego aún no enumera recompensas de rango para esta temporada."
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "El juego no quiso desencantar esto (¿habilidad demasiado baja?). Se omite hasta que recargues."
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "Primero los sonidos de alerta propios del juego y luego los del addon. Cada uno suena al elegirlo."
L["The gap between the two."] = "El espacio entre los dos."
L["The gap between two buttons."] = "El espacio entre dos botones."
L["The Gear Sets window, with every set and what you can do with it."] = "La ventana de Conjuntos de equipo, con cada conjunto y lo que puedes hacer con él."
L["The group can be disbanded once the fight is over."] = "El grupo se puede disolver cuando termine el combate."
L["The group's paladins and the blessing each gives every class."] = "Los paladines del grupo y la bendición que cada uno da a cada clase."
L["The guild name under a player's name."] = "El nombre de la hermandad bajo el nombre de un jugador."
L["The highest rank this season"] = "El rango más alto de esta temporada"
L["The icon grows and shrinks with it."] = "El ícono crece y se encoge con él."
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "La ventana de inspección con el aspecto de la lista BiS, con su puntuación, revisión de equipo, talentos e historial."
L["The item's cooldown sweeps over its icon."] = "El tiempo de reutilización del objeto barre su ícono."
