L["the pattern"] = "el patrón"
L["The people and projects behind Naowh Forever."] = "Las personas y proyectos detrás de Naowh Forever."
L["The picked boss's loot and abilities, under the map."] = "El botín y las habilidades del jefe elegido, bajo el mapa."
L["The planner's own window, and a mini bar to leave up while you level."] = "La ventana propia del planificador, y una minibarra para dejar visible mientras subes de nivel."
L["The player list opens after combat."] = "La lista de jugadores se abre después del combate."
L["The player's guild rank beside their guild name."] = "El rango de hermandad del jugador junto al nombre de su hermandad."
L["The point of the bar that attaches."] = "El punto de la barra que se adjunta."
L["The point of the frame it attaches to."] = "El punto del marco al que se adjunta."
L["The purchase failed."] = "La compra falló."
L["The purchase failed; the price may have changed."] = "La compra falló; puede que el precio haya cambiado."
L["The purchase failed; the price may have changed.|r"] = "La compra falló; puede que el precio haya cambiado.|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "El rastreador de misiones, y compartir misiones de calabozo con tu grupo."
L["The quests that reward a pick you do not have yet."] = "Las misiones que recompensan una elección que aún no tienes."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "El cuestionario se abre cuando te sientas en una fogata y se cierra cuando te levantas."
L["The raid marker Mark Focus puts on your focus."] = "La marca de banda que Marcar foco pone en tu foco."
L["the rank before"] = "el rango anterior"
L["The ready ring shows with GCD Sweep on."] = "El anillo de listo se muestra con Barrido del TRG activado."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "Los componentes que usan tus hechizos conocidos, como Polvo arcano, velas, semillas, Símbolos de reyes y Polvo destellante, según el rango más alto que conoces."
L["The red time left blinks, to catch your eye."] = "El tiempo restante en rojo parpadea para llamar tu atención."
L["The same required-level filter applies to every stack, not each item separately."] = "El mismo filtro de nivel requerido se aplica a todos los montones, no a cada objeto por separado."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "Los mismos conjuntos que los de la hoja de personaje: equípalos, guárdalos, renómbralos o elimínalos en la ventana de Conjuntos de equipo."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "Lo mismo con una Bendición superior, para una clase que comparte una bendición, mientras llevas Símbolos de reyes."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "Los segundos restantes cuando el tiempo se vuelve rojo; se vuelve amarillo al doble de eso."
L["The serializer libraries are missing from this build."] = "Faltan las bibliotecas de serialización en esta versión."
L["The shape of Naowh's arrow."] = "La forma de la flecha de Naowh."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "La parte de lo que valen los objetos que la propina sugerida agrega, además de reponer los materiales propios del artesano. Al menos 1p a menos que se ponga en 0."
L["The shortest time between two thanks to the same player."] = "El tiempo mínimo entre dos agradecimientos al mismo jugador."
L["The Slot"] = "La casilla"
L["The slot it is for."] = "La casilla para la que es."
L["The slots and stats only"] = "Solo las casillas y estadísticas"
L["The space between Naowh's arrow and the text under it."] = "El espacio entre la flecha de Naowh y el texto debajo."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "La especialización para la que se valora tu equipo. Automático sigue tus talentos: el árbol con más puntos (el Feral de un druida se valora para daño; elige Tanque feral para un oso)."
L["The spot ahead of you, 312 yards away."] = "El lugar delante de ti, a 312 m."
L["The spot off to your right."] = "El lugar a tu derecha."
L["The stat weights each spec starts with."] = "Los pesos de estadísticas con los que empieza cada especialización."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "El texto de sigilo mientras estás en sigilo, además del recordatorio cuando no lo estás."
L["The step and distance text under RestedXP's waypoint arrow."] = "El texto de paso y distancia bajo la flecha de punto de ruta de RestedXP."
L["The string is damaged: copy it again in full."] = "La cadena está dañada: vuelve a copiarla completa."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "La propina sugerida repone los materiales del artesano más el %d%% de lo que valen los objetos (de todos los materiales, para una receta que no fabrica ningún objeto), redondeada, al menos 1p. Pon tu propia propina en la lista de pedidos de la derecha. Cambia la proporción en la configuración de Profesiones."
L["The swing timer needs WoW: Forever's own swing event."] = "El temporizador de golpes necesita el evento de golpe propio de WoW: Forever."
L["The tag in the speaker's class color. Off, it is grey."] = "La etiqueta con el color de clase de quien habla. Desactivado, es gris."
L["the talent above it"] = "el talento de arriba"
L["The talent builds you saved in the Training Planner."] = "Las builds de talentos que guardaste en el Planificador de entrenamiento."
L["The Team"] = "El equipo"
L["The text in the theme's accent color instead of gold."] = "El texto en el color de acento del tema en lugar de dorado."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "El tema que usa RestedXP: el suyo o uno de los temas de Naowh."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "La hora entre los dos lados. Haz clic para el calendario (no con mando)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "El tiempo restante se vuelve amarillo y luego rojo cerca del final, para que veas cuándo está por romperse el control de masas."
L["The time left, turning yellow, then red, as the camp runs down."] = "El tiempo restante, que se vuelve amarillo y luego rojo, a medida que se agota el campamento."
L["The tint on every button's icon: Naowh's own and any addon's."] = "El tinte del ícono de cada botón: los de Naowh y los de cualquier addon."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "La ayuda del Planificador de entrenamiento mientras subes de nivel: un aviso al subir de nivel con hechizos para entrenar, y un panel junto a tu instructor de clase."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "El marco de unidad al que está adjunta la barra, o UIParent para la pantalla."
L["The weights"] = "Los pesos"
L["The weights for %s."] = "Los pesos para %s."
L["The window's border fades with it."] = "El borde de la ventana se desvanece con ella."
L["The word itself."] = "La palabra en sí."
L["The XP of completed quests, and their text."] = "La EXP de las misiones completadas, y su texto."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "La EXP de las misiones aún en curso, como un segmento desvanecido después de las completadas."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "La EXP de las misiones aún en curso. De forma predeterminada, el color de misiones completadas, desvanecido."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "La zona de quien habla en un canal de chat, el chat de hermandad o un susurro, delante de su mensaje. El juego nunca dice dónde está un desconocido, así que un jugador queda etiquetado cuando está en el Buscador de grupos, tu hermandad, tus amigos o tu grupo, apareció en un /who o respondió desde su propia copia de Naowh Forever. Su primer mensaje puede llegar sin etiqueta."
L["Their BiS"] = "Su BiS"
L["THEIR GEAR"] = "SU EQUIPO"
L["Their gear, talents and history"] = "Su equipo, talentos e historial"
L["their materials + %d%%"] = "sus materiales + %d%%"
L["Their materials:"] = "Sus materiales:"
L["Their Naowh Score at the top of the panel, with yours under it."] = "Su Naowh Score arriba del panel, con el tuyo debajo."
L["Their supporter badge in the window's corner, if they have one."] = "Su insignia de colaborador en la esquina de la ventana, si tiene una."
L["Thelsamar"] = "Thelsamar"
L["Them"] = "Ellos"
L["them all."] = "todos."
L["Theme"] = "Tema"
L["Theme presets for the addon's windows and HUD frames, plus a Custom option for your own colors. If text gets hard to read, pick Naowh (default). Saved for this computer.|n|nTakes effect after a /reload."] = "Temas predefinidos para las ventanas y marcos del HUD del addon, más una opción Personalizado para tus propios colores. Si el texto se vuelve difícil de leer, elige Naowh (predeterminado). Guardado para esta computadora.|n|nSe aplica después de un /reload."
