L["A glow around each reminder icon, since each is a buff that is missing or running out."] = "Un brillo alrededor de cada ícono de recordatorio, ya que cada uno es un beneficio que falta o se está agotando."
L["A glow around the icon while it shows."] = "Un brillo alrededor del ícono mientras se muestra."
L["A glow around the reminder while you have no Camp Benefits."] = "Un brillo alrededor del recordatorio mientras no tienes Beneficios de campamento."
L["A minimap button that opens %s. Saved for this computer."] = "Un botón del minimapa que abre %s. Guardado para esta computadora."
L["A panel behind the whole window."] = "Un panel detrás de toda la ventana."
L["A progress bar of the guide, a line, or nothing."] = "Una barra de progreso de la guía, una línea o nada."
L["A reminder when a weapon has no sharpening stone, weightstone or oil on it."] = "Un recordatorio cuando un arma no tiene piedra de afilar, piedra de peso ni aceite."
L["A row that is done and the steps after the active one."] = "Una fila completada y los pasos posteriores al activo."
L["A sample: the meter in the game shows your fights."] = "Una muestra: el medidor en el juego muestra tus combates."
L["A soft shine along the top of the bar and a glow where your XP ends."] = "Un brillo suave a lo largo de la parte superior de la barra y un resplandor donde termina tu EXP."
L["A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level."] = "Un texto alrededor de la barra: haz clic en él en la vista previa para cambiarlo. Cada texto se muestra en un solo lugar alrededor de ella: elegir uno que se muestra en otro lugar lo mueve ahí. Solo Tiempo jugado y Tiempo de sesión se muestran en el nivel máximo."
L["About %d kills of your level"] = "Unas %d muertes de tu nivel"
L["Accent Color"] = "Color de acento"
L["Add more consumables to watch in the AuraBuffs window."] = "Agrega más consumibles para vigilar en la ventana de AuraBuffs."
L["Added next to your saved bar sets, never over them"] = "Se agrega junto a tus conjuntos de barras guardados, nunca encima"
L["Adds the Naowh themes to RestedXP's theme list, in place of the Naowh window."] = "Agrega los temas de Naowh a la lista de temas de RestedXP, en lugar de la ventana de Naowh."
L["All Stocked"] = "Todo abastecido"
L["All Texts"] = "Todos los textos"
L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest on this class; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "Alt+clic en una recompensa que puedas elegir, en el registro de misiones o con quien da la misión, para guardarla para esa misión en esta clase; Alt+clic de nuevo para borrarla. Se selecciona al entregar la misión, y Entregar misiones la toma por ti."
L["Ctrl-click an item in your bags to mark it as junk, and sell it at the next vendor."] = "Ctrl+clic en un objeto de tus bolsas para marcarlo como basura y venderlo en el próximo vendedor."
