L["Deathroll: %s and %s are playing for %s."] = "Deathroll: %s y %s juegan por %s."
L["Default: the item you carry, or the kind's usual icon. Last Used: the icon of the food, flask, elixir, scroll or weapon item you used last."] = "Predeterminado: el objeto que llevas, o el ícono habitual del tipo. Último usado: el ícono de la comida, frasco, elixir, pergamino u objeto de arma que usaste por última vez."
