L["A name without its last name gets it the next time you log in on that character."] = "Un nombre sin su apellido lo obtiene la próxima vez que inicies sesión con ese personaje."
L["Every module enabled for the full Naowh Forever experience. Great if you're a power user with addons and want all the bells and whistles."] = "Todos los módulos activados para la experiencia completa de Naowh Forever. Ideal si eres un usuario avanzado de addons y quieres todas las funciones."
