L["On: any flask, elixir or buff food in your bags reminds you, listed or not; off: even with none."] = "Activado: cualquier frasco, elixir o comida de beneficio en tus bolsas te lo recuerda, esté en la lista o no; desactivado: incluso sin ninguno."
