L["A .png, .tga or .blp file. Make its width and height powers of two, such as 128, 256, 512 or 1024, to be safe; a small one, 128 or 256, is good for a pattern that is repeated with Tile Image, and Tile Size says how wide each repeat is. A .jpg is most likely not read by the game: open it and save it as a .png first."] = "Un archivo .png, .tga o .blp. Por seguridad, haz que su ancho y alto sean potencias de dos, como 128, 256, 512 o 1024; uno pequeño, de 128 o 256, va bien para un patrón que se repite con Imagen en mosaico, y Tamaño del mosaico indica qué tan ancha es cada repetición. Es muy probable que el juego no lea un .jpg: ábrelo y guárdalo primero como .png."
