L["With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep that one copy, or Shift-right-click to keep every copy of it, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts."] = "Con Encantamiento abierto, un botón Desencantar en la parte superior de la ventana abre una ventana con cada objeto de tus bolsas que puedes desencantar: armas y armaduras verdes, azules y moradas (o escribe /naowh disenchant). Clic derecho en un objeto para conservar esa copia, o Mayús+clic derecho para conservar todas sus copias, en cualquier personaje, hasta que vuelvas a hacer clic derecho en él. Desencantar todo desencanta el resto uno por uno, un objeto por clic, ya que el juego pide un clic por cada desencantamiento. Un objeto que el juego no acepte (habilidad demasiado baja) se omite hasta que recargues. Se cierra al empezar el combate."
