L["Daily Word First"] = "Palabra del día primero"
L["Opens the Daily Word first until today's is done; closing it opens your game."] = "Abre primero la Palabra del día hasta que termines la de hoy; al cerrarla se abre tu juego."
L["Placed when learned:"] = "Se coloca al aprenderse:"
L["(level %d)"] = "(nivel %d)"
L["Fills in as you learn them"] = "Se completan al aprenderlos"
