L["Not available with the Gamepad interface style"] = "No disponible con el estilo de interfaz de mando"
L["The world map cannot be opened from Naowh Forever with a gamepad."] = "El mapa del mundo no se puede abrir desde Naowh Forever con un mando."
L["Show Buff Range"] = "Mostrar alcance de beneficios"
L["Shows how many missing buffs are in casting range and dims icons with none confirmed."] = "Muestra cuántos beneficios faltantes están al alcance de lanzamiento y atenúa los íconos sin ninguno confirmado."
L["Hide Out of Range"] = "Ocultar fuera de alcance"
L["Hides a raid buff until someone missing it is in casting range."] = "Oculta un beneficio de banda hasta que alguien que no lo tiene esté al alcance de lanzamiento."
L["Hide in the World at Level 60"] = "Ocultar en el mundo en el nivel 60"
L["At level 60, consumable reminders stay out of the open world."] = "En el nivel 60, los recordatorios de consumibles no aparecen en el mundo abierto."
